    seen = set()
    for k, _ in pairs:
        if k in seen:
            raise ValueError('DUPLICATE KEY: ' + k)
        seen.add(k)
    return dict(pairs)


def sload(p):
    """Strict JSON admission. Duplicate object keys are rejected, not silently last-wins."""
    with open(p, encoding='utf-8') as fh:
        return json.load(fh, object_pairs_hook=_no_dup)


